WITH kept_keys AS (SELECT status, method FROM payments INTERSECT SELECT status, method FROM payments WHERE TO_DATE(paid_at) < '2024-04-04'), kept_rows AS (SELECT s.* FROM payments s INNER JOIN kept_keys k ON s.status = k.status AND s.method = k.method), scored AS (SELECT id, order_id, method, amount, paid_at, status, MAX(amount) OVER (PARTITION BY method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_max_30d, RANK() OVER (ORDER BY amount DESC NULLS LAST) AS amount_rank, MAX(amount) OVER (PARTITION BY status ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_max_30d_2, DENSE_RANK() OVER (PARTITION BY status ORDER BY amount DESC NULLS FIRST) AS amount_dense_rank, CUME_DIST() OVER (PARTITION BY status, method ORDER BY amount DESC NULLS LAST) AS amount_cume_dist FROM kept_rows), cleaned AS (SELECT id, order_id, method, amount, paid_at, status, amount_max_30d, amount_rank, amount * amount_max_30d_2 AS amount_times_amount_max_30d_2, COALESCE(method, 'UNKNOWN') AS resolved_method FROM scored WHERE amount_max_30d_2 = 907), filtered AS (SELECT id, paid_at, status, amount_max_30d, amount_rank, amount_times_amount_max_30d_2, resolved_method, TRIM(method) AS clean_method, FLOOR(amount_times_amount_max_30d_2) AS amount_times_amount_max_30d_2_whole, COALESCE(method, 'NONE') AS resolved_method_2 FROM cleaned WHERE order_id IS NOT NULL AND amount_times_amount_max_30d_2 < 44), valid AS (SELECT *, CAST(amount_times_amount_max_30d_2_whole AS DOUBLE) AS amount_times_amount_max_30d_2_whole_num, DATE_TRUNC('MONTH', paid_at) AS paid_at_period FROM filtered WHERE paid_at > DATE '2023-06-21') SELECT id, status, amount_max_30d, amount_rank, resolved_method, clean_method, amount_times_amount_max_30d_2_whole, resolved_method_2, paid_at_period, CASE WHEN status RLIKE '^(REFUNDED|FAILED)$' THEN 'GROUP_B' WHEN status RLIKE '^(SUCCESS)$' THEN 'CORE' ELSE 'GROUP_A' END AS status_zone FROM valid ORDER BY status DESC
